const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const vesuvius = ee.Geometry.Point([14.426, 40.821]).buffer(1000); // 1km buffer around cone
  const date = '2022-01-02';

  // 2. Data Acquisition
  const landsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(vesuvius)
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  const size = landsat.size().getInfo();
  console.log(`Landsat 8 images on ${date}: ${size}`);

  if (size === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  const image = landsat.first();

  // 3. Cloud detection from QA_PIXEL band
  // Landsat 8 Collection 2 QA_PIXEL bits:
  // Bit 3: Cloud shadow (1 = yes)
  // Bit 4: Snow (1 = yes) 
  // Bit 5: Cloud (1 = yes)
  const qa = image.select('QA_PIXEL');
  const cloudBit = 1 << 5;
  const cloudMask = qa.bitwiseAnd(cloudBit).neq(0);

  // 4. Count pixels
  const stats = image.select('SR_B3').addBands(cloudMask).reduceRegion({
    reducer: ee.Reducer.count().forEachBand(['SR_B3', 'QA_PIXEL']),
    geometry: vesuvius,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const totalPixels = stats.SR_B3;
  const cloudPixels = stats.QA_PIXEL;

  console.log(`Total pixels: ${totalPixels}`);
  console.log(`Cloud pixels: ${cloudPixels}`);

  if (totalPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  const cloudCoverage = (cloudPixels / totalPixels) * 100;
  console.log(`Cloud coverage: ${cloudCoverage.toFixed(1)}%`);

  // 5. Validation & Final Answer
  if (cloudCoverage >= 99.9) { // Allow for minor edge cases
    console.log("<answer>A</answer>");
  } else if (cloudCoverage >= 0) {
    console.log("<answer>B</answer>");
  } else {
    console.log("<answer>C3</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
